 const Q4=(b,a,c,d,f,n,uv)=>{const i0=V(b,a[0],a[1],a[2],n[0],n[1],n[2],uv[0][0],uv[0][1]),i1=V(b,c[0],c[1],c[2],n[0],n[1],n[2],uv[1][0],uv[1][1]),i2=V(b,d[0],d[1],d[2],n[0],n[1],n[2],uv[2][0],uv[2][1]),i3=V(b,f[0],f[1],f[2],n[0],n[1],n[2],uv[3][0],uv[3][1]);b.i.push(i0,i1,i2,i0,i2,i3)};
