   T.hasAlpha=!0;T.update(!0);const mt=new yL(`c9-n-inscrM`,sc);mt.diffuseTexture=T;mt.useAlphaFromDiffuseTexture=!0;mt.emissiveColor=h6(`#8a8068`);mt.specularColor=h6(`#000000`);mt.backFaceCulling=!0;
