 // ПЕРЕСТРОЙКА ДОРОГ: старые тонкие ленты x8 скрываем, вместо них ставим
 // непрерывные сегменты-плиты с видимым верхом и настоящим checkCollisions.
 const surfaceRoute=(name,pts,width,top,material,thick=.28)=>{
   const oldMesh=sc.getMeshByName(name); if(oldMesh) oldMesh.isVisible=false;
   const SR=window.SevRoad;
   if(SR&&pts.length>=2){ /* v182: одна цельная плита с плавными поворотами вместо прямоугольных кусков; коллизия по её форме */
     let P=pts.map(p=>[p.x,p.z]);
     const f0=P[0],f1=P[1],g0=P[P.length-1],g1=P[P.length-2],la=Math.hypot(f0[0]-f1[0],f0[1]-f1[1])||1,lb=Math.hypot(g0[0]-g1[0],g0[1]-g1[1])||1;
     P[0]=[f0[0]+(f0[0]-f1[0])/la*.65,f0[1]+(f0[1]-f1[1])/la*.65];P[P.length-1]=[g0[0]+(g0[0]-g1[0])/lb*.65,g0[1]+(g0[1]-g1[1])/lb*.65];
     if(P.length>2)P=SR.fillet(P,P.map((_,k)=>k===0||k===P.length-1?1:0),Math.max(6,width*1.6),1.5);
     P=SR.dens(P,6);
     const R=SR.ribbon(P,-width/2,width/2),yb=top-thick,pos=[],ind=[],uv=[],nn=P.length;
     for(let i=0;i<nn;i++){const L=R.L[i],Rr=R.R[i],v=R.acc[i]/Math.max(2,width);
       pos.push(L[0],top,L[1],Rr[0],top,Rr[1],L[0],yb,L[1],Rr[0],yb,Rr[1]);uv.push(0,v,1,v,0,v,1,v)}
     for(let i=0;i<nn-1;i++){const a=i*4,b=a+4;
       ind.push(a,b+1,a+1,a,b,b+1);          /* верх */
       ind.push(a+2,a+3,b+3,a+2,b+3,b+2);    /* низ */
       ind.push(a,a+2,b+2,a,b+2,b);          /* левый край */
       ind.push(a+1,b+1,b+3,a+1,b+3,a+3)}    /* правый край */
     const z=(nn-1)*4;ind.push(0,1,3,0,3,2,z,z+2,z+3,z,z+3,z+1);
     let nr=[];wl.ComputeNormals(pos,ind,nr);if(nr[1]<0){for(let i=0;i<ind.length;i+=3){const t=ind[i+1];ind[i+1]=ind[i+2];ind[i+2]=t}nr=[];wl.ComputeNormals(pos,ind,nr)}
     const m=new Q(`${name}-driveable`,sc),vd=new wl;vd.positions=pos;vd.indices=ind;vd.normals=nr;vd.uvs=uv;vd.applyToMesh(m);
     e._finish(m,{collide:!0,isStatic:!0,receive:!0,material});m.isPickable=!0;m.computeWorldMatrix(!0);m.freezeWorldMatrix();return}
   for(let i=0;i<pts.length-1;i++){
     const a=pts[i],b=pts[i+1],dx=b.x-a.x,dz=b.z-a.z,len=Math.hypot(dx,dz);
     if(len<.1) continue;
     const deck=e.box(`${name}-driveable-${i}`,[width,thick,len+1.35],[ (a.x+b.x)/2, top-thick, (a.z+b.z)/2 ],material,{collide:!0,isStatic:!0,receive:!0,cast:!1});
     deck.rotation.y=Math.atan2(dx,dz); deck.computeWorldMatrix(!0); deck.freezeWorldMatrix();
   }
 };
