  for(let i=westA-6;i<=westB+6&&i<nS;i+=4){if(i<0)continue;const p=off(i,-41);const l=plant(rnd()<.6?'poplar':'plane',p.x,p.z,.9+rnd()*.3);if(i%8===0)e.shadowCasters.push(...l)}
  for(let i=0;i<nS-1;i+=5){const p=off(i,-20+(i%2?-4:0)),z=p.z;if(i>=westA-6&&i<=westB+6)continue;plant(trees[i%4],p.x,p.z,.9+rnd()*.4)}
