  for(let k=0;k<ARMS.length;k++){const arm=ARMS[k];for(let t=0;t<arm.length-1;t++){const a=arm[t],b=arm[t+1];coinsL.push([(a[0]+b[0])/2,1.5,(a[1]+b[1])/2])}}
  for(const p of PIERS){if(!(p.len>0))continue;const i=idxZ(p.z,p.side),a=S[i],n=N[i];for(const d of[12,28,p.len-3])coinsL.push([a.x+n.x*d,1.4,a.z+n.z*d])}
