  n.slab('ow-brest-land',[-430,-298],[-476,-390],.012,grass,solid);
  n.slab('ow-pocket-land',[-358,-294],[-394,-294],.009,grass,solid);   /* заливаем «карман» моря между участками суши */
  /* --- пр. Октябрьской Революции → ring-road бухты Омега --- */
  const linkR=[{x:-408,z:-250},{x:-450,z:-250},{x:-497,z:-250}];
  SR('ow-link',linkR,11.6,road);SR('ow-link-sw-n',side(linkR,0,-8.2),2.5,walk,.13,.22);SR('ow-link-sw-s',side(linkR,0,8.2),2.5,walk,.13,.22);
  for(let x=-418;x>-492;x-=10)n.box(`ow-link-dash-${x}`,[2.1,.035,.16],[x,.205,-250],line,{receive:!0});
  for(let x=-420;x>-495;x-=24)w8(n,`ow-link-lamp-${x}`,x,-241,4.9);
