  const heroesS=[{x:-390,z:-410},{x:-390,z:-431.5}];
  const brest=[{x:-390,z:-431.5},{x:-500,z:-431.5},{x:-620,z:-431.5},{x:-740,z:-431.5},{x:-790,z:-431.5}];
  SR('ow-heroes-s',heroesS,11.6,road);SR('ow-heroes-s-w',side(heroesS,-8.2,0),2.5,walk,.13,.22);SR('ow-heroes-s-e',side(heroesS,8.2,0),2.5,walk,.13,.22);
  n.box('ow-brest-junction',[22,.32,22],[-390,-.13,-431.5],road,{collide:!0,isStatic:!0,receive:!0});
  SR('ow-brest',brest,11.6,road);SR('ow-brest-sw-n',side(brest.slice(1),0,8.2),2.5,walk,.13,.22);SR('ow-brest-sw-s',side(brest.slice(1),0,-8.2),2.5,walk,.13,.22);
  for(let x=-405;x>-785;x-=10)n.box(`ow-brest-dash-${x}`,[2.1,.035,.16],[x,.205,-431.5],line,{receive:!0});
  for(let x=-410;x>-785;x-=30)w8(n,`ow-brest-lamp-${x}`,x,-423,4.9);
