  const kol=[{x:30,z:-388},{x:30,z:-340},{x:30,z:-286},{x:30,z:-230},{x:30,z:-188}];
  SR('ow-kol',kol,9,road);SR('ow-kol-w',side(kol,-6.6,0),2.2,walk,.13,.22);SR('ow-kol-e',side(kol,6.6,0),2.2,walk,.13,.22);
  n.box('ow-kol-junction',[22,.32,20],[30,-.13,-286],road,{collide:!0,isStatic:!0,receive:!0});
