  for(let z=-370;z<-190;z+=34){if(Math.abs(z+286)<20)continue;w8(n,`ow-kol-lamp-a${z}`,23,z,4.9);w8(n,`ow-kol-lamp-b${z}`,37,z+10,4.9)}
