  n.box('ow-gate-post',[.5,2.6,.5],[304,0,-292],dark,{cast:!0});n.box('ow-gate-arm',[.25,.25,13],[304,2.3,-286],n.mat('#d9352b'),{cast:!0});
  for(let k=0;k<4;k++)n.box(`ow-gate-stripe${k}`,[.27,.27,1.4],[304,2.3,-291+k*3.3],line);
