      {const hide=!!(gm.card&&gm.card.isOpen);const dsp=hide?'none':'';if(box.style.display!==dsp){box.style.display=dsp;N.style.display=dsp;SN.style.display=dsp}if(hide)return}
      if(!LB&&window.__sevRD)build();
