      g.fillStyle='#3a6fb0';g.fillRect(0,0,300,300);
      if(ok){const px=(x-M.x0)/M.res,py=(M.z1-z)/M.res,s=R/M.res;g.drawImage(img,px-s,py-s,2*s,2*s,0,0,300,300)}
      /* машины */
      g.fillStyle='#ffd23f';for(const car of (window.__sevCoastCars||[])){const dx=(car.x-x)/R*C,dz=(car.z-z)/R*C;if(dx*dx+dz*dz<148*148)g.fillRect(C+dx-3,C-dz-3,6,6)}
